const crypto = require('crypto');
const E = (e) => `${e.code ?? e.name} | ${String(e.message).split('\n')[0]}`;
const t = (l, f) => { try { console.log(l, '->', f()); } catch (e) { console.log(l, '-> THROW', E(e)); } };
console.log('getCiphers', crypto.getCiphers().length, crypto.getCiphers().filter((c) => /aes|des|chacha/i.test(c)).join(','));
const rnd = (n, seed) => { const b = Buffer.alloc(n); let s = seed; for (let i = 0; i < n; i++) { s = (s * 1103515245 + 12345) >>> 0; b[i] = s >>> 24; } return b; };
const pt = rnd(1000, 9), pts = { empty: Buffer.alloc(0), one: Buffer.from('x'), b16: rnd(16, 4), b1000: pt };
const enc = (alg, key, iv, data, opts, aad) => { const c = crypto.createCipheriv(alg, key, iv, opts); if (aad) c.setAAD(aad, opts && { plaintextLength: data.length }); const o = Buffer.concat([c.update(data), c.final()]); const tag = /gcm|ccm|ocb|poly/.test(alg) ? c.getAuthTag().toString('hex') : ''; return [o, tag]; };
const dec = (alg, key, iv, data, opts, aad, tag) => { const d = crypto.createDecipheriv(alg, key, iv, opts); if (tag) d.setAuthTag(Buffer.from(tag, 'hex')); if (aad) d.setAAD(aad, opts && { plaintextLength: data.length }); return Buffer.concat([d.update(data), d.final()]); };
const sizes = { 128: 16, 192: 24, 256: 32 };
for (const mode of ['cbc', 'ctr', 'ecb', 'cfb', 'cfb8', 'cfb1', 'ofb', 'gcm']) for (const bits of [128, 192, 256]) {
  const alg = `aes-${bits}-${mode}`; const key = rnd(sizes[bits], bits); const iv = mode === 'ecb' ? null : rnd(mode === 'gcm' ? 12 : 16, 77);
  for (const [n, d] of Object.entries(pts)) t(`${alg} ${n}`, () => { const [o, tag] = enc(alg, key, iv, d); const back = dec(alg, key, iv, o, undefined, undefined, tag); return `${o.toString('hex').slice(0, 64)}… len=${o.length} tag=${tag} rt=${back.equals(d)}`; });
}
t('aes-256-cbc nopadding 16', () => { const c = crypto.createCipheriv('aes-256-cbc', rnd(32, 1), rnd(16, 2)); c.setAutoPadding(false); return Buffer.concat([c.update(rnd(32, 3)), c.final()]).toString('hex'); });
t('aes-256-cbc nopadding 15', () => { const c = crypto.createCipheriv('aes-256-cbc', rnd(32, 1), rnd(16, 2)); c.setAutoPadding(false); return Buffer.concat([c.update(rnd(15, 3)), c.final()]).toString('hex'); });
t('aes-256-cbc bad padding decrypt', () => dec('aes-256-cbc', rnd(32, 1), rnd(16, 2), rnd(32, 5)).toString('hex'));
t('aes-256-cbc wrong key', () => dec('aes-256-cbc', rnd(32, 9), rnd(16, 2), enc('aes-256-cbc', rnd(32, 1), rnd(16, 2), pt)[0]).length);
t('aes bad key length', () => crypto.createCipheriv('aes-256-cbc', rnd(31, 1), rnd(16, 2)));
t('aes bad iv length', () => crypto.createCipheriv('aes-256-cbc', rnd(32, 1), rnd(15, 2)));
t('unknown cipher', () => crypto.createCipheriv('aes-999-cbc', rnd(32, 1), rnd(16, 2)));
const K = rnd(32, 11), IV = rnd(12, 12), AAD = Buffer.from('header-aad');
const [gc, gtag] = enc('aes-256-gcm', K, IV, pt, undefined, AAD);
t('gcm aad tag', () => gtag);
t('gcm verify ok', () => dec('aes-256-gcm', K, IV, gc, undefined, AAD, gtag).equals(pt));
t('gcm tampered tag', () => { const bad = Buffer.from(gtag, 'hex'); bad[0] ^= 1; return dec('aes-256-gcm', K, IV, gc, undefined, AAD, bad.toString('hex')).length; });
t('gcm tampered ciphertext', () => { const c = Buffer.from(gc); c[10] ^= 0x80; return dec('aes-256-gcm', K, IV, c, undefined, AAD, gtag).length; });
t('gcm tampered aad', () => dec('aes-256-gcm', K, IV, gc, undefined, Buffer.from('header-aaD'), gtag).length);
t('gcm missing aad', () => dec('aes-256-gcm', K, IV, gc, undefined, undefined, gtag).length);
t('gcm no tag set', () => { const d = crypto.createDecipheriv('aes-256-gcm', K, IV); d.setAAD(AAD); d.update(gc); return d.final().length; });
t('gcm truncated tag 8 default', () => dec('aes-256-gcm', K, IV, gc, undefined, AAD, gtag.slice(0, 16)).length);
t('gcm authTagLength 8', () => { const [c, tg] = enc('aes-128-gcm', K.subarray(0, 16), IV, pt, { authTagLength: 8 }, AAD); return [tg, dec('aes-128-gcm', K.subarray(0, 16), IV, c, { authTagLength: 8 }, AAD, tg).equals(pt)].join(' '); });
t('gcm authTagLength 7 invalid', () => crypto.createCipheriv('aes-128-gcm', K.subarray(0, 16), IV, { authTagLength: 7 }));
t('gcm tag length mismatch', () => dec('aes-128-gcm', K.subarray(0, 16), IV, gc, { authTagLength: 8 }, AAD, gtag).length);
t('gcm iv 16 bytes', () => enc('aes-256-gcm', K, rnd(16, 3), pt)[1]);
t('gcm iv 1 byte', () => enc('aes-256-gcm', K, rnd(1, 3), pt)[1]);
t('gcm getAuthTag before final', () => { const c = crypto.createCipheriv('aes-256-gcm', K, IV); c.update(pt); return c.getAuthTag(); });
t('gcm streaming splits', () => { const c = crypto.createCipheriv('aes-256-gcm', K, IV); c.setAAD(AAD); const parts = []; for (let i = 0; i < pt.length; i += 37) parts.push(c.update(pt.subarray(i, i + 37))); parts.push(c.final()); return [Buffer.concat(parts).equals(gc), c.getAuthTag().toString('hex') === gtag].join(','); });
t('gcm nist tc2 (128, zero key/iv/pt)', () => { const c = crypto.createCipheriv('aes-128-gcm', Buffer.alloc(16), Buffer.alloc(12)); const o = Buffer.concat([c.update(Buffer.alloc(16)), c.final()]); return [o.toString('hex'), c.getAuthTag().toString('hex')].join(' '); });
t('ccm', () => enc('aes-128-ccm', K.subarray(0, 16), IV.subarray(0, 12), pt, { authTagLength: 16 }, AAD)[1]);
t('chacha20-poly1305', () => enc('chacha20-poly1305', K, IV, pt, { authTagLength: 16 })[1]);
for (const alg of ['des-ede3-cbc', 'des-ede3', 'des-ede-cbc', 'des-cbc', 'des-ecb', 'des-ede3-cfb']) t(alg, () => { const kl = /ede3/.test(alg) ? 24 : /ede/.test(alg) ? 16 : 8; const iv = /ecb|^des-ede3$/.test(alg) ? null : rnd(8, 5); const [o] = enc(alg, rnd(kl, 6), iv, pt); return `${o.toString('hex').slice(0, 48)} len=${o.length} rt=${dec(alg, rnd(kl, 6), iv, o).equals(pt)}`; });
t('cipher string io', () => { const c = crypto.createCipheriv('aes-128-cbc', K.subarray(0, 16), rnd(16, 1)); return c.update('hello', 'utf8', 'base64') + c.final('base64'); });
t('cipher stream', () => 'below');
const cs = crypto.createCipheriv('aes-128-ctr', K.subarray(0, 16), rnd(16, 1)); const outs = []; cs.on('data', (d) => outs.push(d)); cs.on('end', () => console.log('cipher stream ->', Buffer.concat(outs).toString('hex').slice(0, 40))); cs.write('abc'); cs.end('def');
t('createCipher (deprecated, removed in 22)', () => typeof crypto.createCipher);
t('final twice', () => { const c = crypto.createCipheriv('aes-128-cbc', K.subarray(0, 16), rnd(16, 1)); c.final(); return c.final(); });
